  for _ in range(k): b=rot(b)
  outs += [(f'rot{k}',b),(f'rot{k}flipx',[r[::-1] for r in b]),(f'rot{k}flipy',b[::-1])]
 return outs
best=[]
for name,a in variants(L):
 if len(a)!=H or len(a[0])!=W: continue
 for n,b in variants(R):
