 "content": "def transform(grid):
    """Overlay the two non-background patterns separated by a uniform line;
    color cells occupied on both sides with 2."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    # Locate a full-height or full-width separator line. Its cells are all the
    # same nonzero color, unlike the two pattern regions.
    divider = None
    for x in range(w):
        vals = [grid[y][x] for y in range(h)]
        if vals and vals[0] != 0 and all(v == vals[0] for v in vals):
            divider = ("v", x)
            break
    if divider is None:
        for y in range(h):
            vals = grid[y]
            if vals and vals[0] != 0 and all(v == vals[0] for v in vals):
                divider = ("h", y)
                break
    if divider is None:
        raise ValueError("separator not found")
    axis, pos = divider
    if axis == "v":
        left, right = [row[:pos] for row in grid], [row[pos + 1:] for row in grid]
        n = min(len(left[0]), len(right[0]))
        return [[2 if left[y][x] and right[y][x] else 0 for x in range(n)] for y in range(h)]
    top, bottom = grid[:pos], grid[pos + 1:]
    n = min(len(top), len(bottom))
    return [[2 if top[y][x] and bottom[y][x] else 0 for x in range(w)] for y in range(n)]
